examples += EXAMPLE(3, ('Intermediate', 'Trung bình'), ('Length of a diagonal', 'Độ dài đường chéo'), T('A cube has edge \\(a\\). Find \\(|\\overrightarrow{AC′}|\\).', 'Hình lập phương có cạnh \\(a\\). Tính \\(|\\overrightarrow{AC′}|\\).'),
  T('Use \\(\\overrightarrow{AC′}=\\overrightarrow{AB}+\\overrightarrow{AD}+\\overrightarrow{AA′}\\) and square it.', 'Dùng \\(\\overrightarrow{AC′}=\\overrightarrow{AB}+\\overrightarrow{AD}+\\overrightarrow{AA′}\\) rồi bình phương.'), [T('\\(|\\overrightarrow{AC′}|^2=a^2+a^2+a^2+2(\\overrightarrow{AB}\\cdot\\overrightarrow{AD}+\\dots)\\).', '\\(|\\overrightarrow{AC′}|^2=a^2+a^2+a^2+2(\\overrightarrow{AB}\\cdot\\overrightarrow{AD}+\\dots)\\).'), T('The three edges are perpendicular, so all the dot products are 0.', 'Ba cạnh đôi một vuông góc nên các tích vô hướng đều bằng 0.')], T('\\(|\\overrightarrow{AC′}|=a\\sqrt3\\).', '\\(|\\overrightarrow{AC′}|=a\\sqrt3\\).'))
examples += EXAMPLE(4, ('Intermediate', 'Trung bình'), ('A dot product', 'Một tích vô hướng'), T('A cube has edge 4. Find \\(\\overrightarrow{AB}\\cdot\\overrightarrow{AC}\\) and the angle between them.', 'Hình lập phương có cạnh 4. Tính \\(\\overrightarrow{AB}\\cdot\\overrightarrow{AC}\\) và góc giữa hai vectơ.'),
  T('\\(AC=4\\sqrt2\\) and the angle \\(\\widehat{BAC}=45^\\circ\\).', '\\(AC=4\\sqrt2\\) và góc \\(\\widehat{BAC}=45^\\circ\\).'), [T('\\(\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=4\\cdot4\\sqrt2\\cdot\\cos45^\\circ\\).', '\\(\\overrightarrow{AB}\\cdot\\overrightarrow{AC}=4\\cdot4\\sqrt2\\cdot\\cos45^\\circ\\).'), T('\\(=16\\sqrt2\\cdot\\dfrac{\\sqrt2}{2}=16\\).', '\\(=16\\sqrt2\\cdot\\dfrac{\\sqrt2}{2}=16\\).')], T('The dot product is 16; the angle is \\(45^\\circ\\).', 'Tích vô hướng bằng 16; góc bằng \\(45^\\circ\\).'))
assert _dot(_vec('A', 'B'), _vec('A', 'C')) * 16 == 16
examples += EXAMPLE(5, ('Advanced', 'Nâng cao'), ('Perpendicular vectors', 'Hai vectơ vuông góc'), T('In the cube \\(ABCD.A′B′C′D′\\), show that \\(AC′\\perp BD\\).', 'Trong hình lập phương \\(ABCD.A′B′C′D′\\), chứng minh \\(AC′\\perp BD\\).'),
  T('Write both vectors with \\(\\vec a=\\overrightarrow{AB},\\vec b=\\overrightarrow{AD},\\vec c=\\overrightarrow{AA′}\\).', 'Viết cả hai vectơ theo \\(\\vec a=\\overrightarrow{AB},\\vec b=\\overrightarrow{AD},\\vec c=\\overrightarrow{AA′}\\).'), [T('\\(\\overrightarrow{AC′}=\\vec a+\\vec b+\\vec c\\), \\(\\overrightarrow{BD}=\\vec b-\\vec a\\).', '\\(\\overrightarrow{AC′}=\\vec a+\\vec b+\\vec c\\), \\(\\overrightarrow{BD}=\\vec b-\\vec a\\).'), T('\\(\\overrightarrow{AC′}\\cdot\\overrightarrow{BD}=|\\vec b|^2-|\\vec a|^2=0\\) (the cross terms are 0).', '\\(\\overrightarrow{AC′}\\cdot\\overrightarrow{BD}=|\\vec b|^2-|\\vec a|^2=0\\) (các tích chéo bằng 0).')], T('So \\(AC′\\perp BD\\).', 'Vậy \\(AC′\\perp BD\\).'))
